@page "/apply"
@rendermode InteractiveServer
@using sv_38f5c5618948469c946806378080bd4c.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    @* ───── Step Indicator Bar ───── *@
    <nav class="step-bar">
        @for (int i = 0; i < _stepLabels.Length; i++)
        {
            var step = i;
            var css = step == _currentStep ? "step active"
                    : step < _currentStep ? "step completed"
                    : "step future";

            <button class="@css"
                    disabled="@(step > _currentStep)"
                    @onclick="() => GoToStep(step)">
                <span class="step-number">
                    @if (step < _currentStep)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        @(step + 1)
                    }
                </span>
                <span class="step-label">@_stepLabels[step]</span>
            </button>

            @if (step < _stepLabels.Length - 1)
            {
                <span class="step-connector @(step < _currentStep ? "done" : "")"></span>
            }
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger mt-3">@_errorMessage</div>
    }

    @* ───── Step 1: Personal Info ───── *@
    @if (_currentStep == 0)
    {
        <section class="step-content">
            <h2>Personal Information</h2>

            <div class="mb-3">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_fullName" placeholder="Jane Doe" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input class="form-control" type="email" @bind="_email" placeholder="jane@example.com" />
                @if (_emailValidating)
                {
                    <small class="text-muted">Validating email…</small>
                }
            </div>
            <div class="mb-3">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input class="form-control" type="tel" @bind="_phone" placeholder="(555) 123-4567" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <textarea class="form-control" rows="2" @bind="_address" placeholder="123 Main St, City, State ZIP"></textarea>
            </div>

            <div class="step-buttons">
                <span></span>
                <button class="btn btn-primary" @onclick="NextFromPersonal" disabled="@_emailValidating">Next &raquo;</button>
            </div>
        </section>
    }

    @* ───── Step 2: Work History ───── *@
    @if (_currentStep == 1)
    {
        <section class="step-content">
            <h2>Work History</h2>

            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var idx = i;
                var entry = _workEntries[idx];

                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Position @(idx + 1)</h5>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                            }
                        </div>

                        <div class="row g-3">
                            <div class="col-md-6">
                                <label class="form-label">Company <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Company"
                                       @onchange="e => UpdateWork(idx, entry with { Company = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Title"
                                       @onchange="e => UpdateWork(idx, entry with { Title = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                <input class="form-control" type="date" value="@FormatDate(entry.StartDate)"
                                       @onchange="e => UpdateWork(idx, entry with { StartDate = ParseDate((string?)e.Value) })" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">End Date</label>
                                <input class="form-control" type="date"
                                       value="@FormatDate(entry.EndDate)"
                                       disabled="@entry.IsCurrent"
                                       @onchange="e => UpdateWork(idx, entry with { EndDate = ParseNullableDate((string?)e.Value) })" />
                            </div>
                            <div class="col-md-4 d-flex align-items-end">
                                <div class="form-check mb-2">
                                    <input class="form-check-input" type="checkbox" checked="@entry.IsCurrent"
                                           @onchange="e => UpdateWork(idx, entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = null })" />
                                    <label class="form-check-label">Currently employed here</label>
                                </div>
