</div>

@code {
    // ── Step tracking ──
    private int _currentStep;
    private readonly string[] _stepLabels = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    // ── Step 1 state ──
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;
    private bool _emailValidating;

    // ── Step 2 state ──
    private List<WorkEntryModel> _workEntries = new() { new() };

    // ── Step 3 state ──
    private List<ReferenceModel> _references = new() { new(), new() };

    // ── Step 4 state ──
    private string _coverLetter = string.Empty;

    // ── Step 5 state ──
    private bool _submitting;
    private bool _submitted;
    private int _applicationId;

    private string? _errorMessage;

    // ── Navigation ──

    private void GoToStep(int step)
    {
        if (step <= _currentStep)
        {
            _errorMessage = null;
            _currentStep = step;
        }
    }

    private void NextStep()
    {
        _errorMessage = null;
        _currentStep++;
    }

    private void PreviousStep()
    {
        _errorMessage = null;
        _currentStep--;
    }

    // ── Step 1 validation ──

    private async Task NextFromPersonal()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _emailValidating = true;
        try
        {
            var valid = await ApplicationService.ValidateEmailAsync(_email);
            if (!valid)
            {
                _errorMessage = "Please enter a valid email address.";
                return;
            }
        }
        finally
        {
            _emailValidating = false;
        }

        NextStep();
    }

    // ── Step 2 helpers ──

    private void AddWorkEntry() => _workEntries.Add(new());
    private void RemoveWorkEntry(int idx) => _workEntries.RemoveAt(idx);
    private void UpdateWork(int idx, WorkEntryModel entry) => _workEntries[idx] = entry;

    private void NextFromWork()
    {
        _errorMessage = null;

        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
                || entry.StartDate == default)
            {
                _errorMessage = "Please fill in company, title, and start date for every position.";
                return;
            }
        }

        NextStep();
    }

    // ── Step 3 helpers ──

    private void AddReference()
    {
        if (_references.Count < 3) _references.Add(new());
    }

    private void RemoveReference(int idx) => _references.RemoveAt(idx);
    private void UpdateRef(int idx, ReferenceModel r) => _references[idx] = r;

    private void NextFromReferences()
    {
        _errorMessage = null;

        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _errorMessage = "Please fill in all fields for every reference.";
                return;
            }
        }

        NextStep();
    }

    // ── Submit ──

    private async Task SubmitApplication()
    {
        _submitting = true;
        _errorMessage = null;

        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
            var workHistory = new WorkHistory(
                _workEntries.Select(w => new WorkEntry(w.Company, w.Title, w.StartDate, w.IsCurrent ? null : w.EndDate, w.Description)).ToList());
            var refs = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, workHistory, refs, _coverLetter);

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _submitting = false;
        }
    }

    // ── Date helpers ──

    private static string FormatDate(DateTime date) => date == default ? string.Empty : date.ToString("yyyy-MM-dd");
    private static string FormatDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? string.Empty;
    private static DateTime ParseDate(string? value) => DateTime.TryParse(value, out var d) ? d : default;
    private static DateTime? ParseNullableDate(string? value) => DateTime.TryParse(value, out var d) ? d : null;

    // ── Mutable view-models for form binding ──

    private record WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private record ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

.apply-container {
    max-width: 820px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* ── Step indicator bar ── */

.step-bar {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
    margin-bottom: 2rem;
    flex-wrap: wrap;
}

.step-bar .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    padding: 0.5rem 0.75rem;
    cursor: default;
    min-width: 90px;
}

.step-bar .step.completed {
    cursor: pointer;
}

.step-number {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.95rem;
    margin-bottom: 0.35rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #adb5bd;
    transition: all 0.2s;
}

.step.active .step-number {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

.step.completed .step-number {
    background: #198754;
    color: #fff;
    border-color: #198754;
}

.step-label {
    font-size: 0.78rem;
    color: #adb5bd;
    text-align: center;
    white-space: nowrap;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step-connector {
    width: 32px;
    height: 2px;
    background: #dee2e6;
    align-self: center;
    margin-bottom: 1.2rem;
}

.step-connector.done {
    background: #198754;
}

/* ── Step content ── */

.step-content {
