{"file_text": "@page "/apply"
@rendermode InteractiveServer
@using sv_38f5c5618948469c946806378080bd4c.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    @* ───── Step Indicator Bar ───── *@
    <nav class="step-bar">
        @for (int i = 0; i < _stepLabels.Length; i++)
        {
            var step = i;
            var css = step == _currentStep ? "step active"
                    : step < _currentStep ? "step completed"
                    : "step future";

            <button class="@css"
                    disabled="@(step > _currentStep)"
                    @onclick="() => GoToStep(step)">
                <span class="step-number">
                    @if (step < _currentStep)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        @(step + 1)
                    }
                </span>
                <span class="step-label">@_stepLabels[step]</span>
            </button>

            @if (step < _stepLabels.Length - 1)
            {
                <span class="step-connector @(step < _currentStep ? "done" : "")"></span>
            }
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger mt-3">@_errorMessage</div>
    }

    @* ───── Step 1: Personal Info ───── *@
    @if (_currentStep == 0)
    {
        <section class="step-content">
            <h2>Personal Information</h2>

            <div class="mb-3">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_fullName" placeholder="Jane Doe" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input class="form-control" type="email" @bind="_email" placeholder="jane@example.com" />
                @if (_emailValidating)
                {
                    <small class="text-muted">Validating email…</small>
                }
            </div>
            <div class="mb-3">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input class="form-control" type="tel" @bind="_phone" placeholder="(555) 123-4567" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <textarea class="form-control" rows="2" @bind="_address" placeholder="123 Main St, City, State ZIP"></textarea>
            </div>

            <div class="step-buttons">
                <span></span>
                <button class="btn btn-primary" @onclick="NextFromPersonal" disabled="@_emailValidating">Next &raquo;</button>
            </div>
        </section>
    }

    @* ───── Step 2: Work History ───── *@
    @if (_currentStep == 1)
    {
        <section class="step-content">
            <h2>Work History</h2>

            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var idx = i;
                var entry = _workEntries[idx];

                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Position @(idx + 1)</h5>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                            }
                        </div>

                        <div class="row g-3">
                            <div class="col-md-6">
                                <label class="form-label">Company <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Company"
                                       @onchange="e => UpdateWork(idx, entry with { Company = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Title"
                                       @onchange="e => UpdateWork(idx, entry with { Title = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                <input class="form-control" type="date" value="@FormatDate(entry.StartDate)"
                                       @onchange="e => UpdateWork(idx, entry with { StartDate = ParseDate((string?)e.Value) })" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">End Date</label>
                                <input class="form-control" type="date"
                                       value="@FormatDate(entry.EndDate)"
                                       disabled="@entry.IsCurrent"
                                       @onchange="e => UpdateWork(idx, entry with { EndDate = ParseNullableDate((string?)e.Value) })" />
                            </div>
                            <div class="col-md-4 d-flex align-items-end">
                                <div class="form-check mb-2">
                                    <input class="form-check-input" type="checkbox" checked="@entry.IsCurrent"
                                           @onchange="e => UpdateWork(idx, entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = null })" />
                                    <label class="form-check-label">Currently employed here</label>
                                </div>
                            </div>
                            <div class="col-12">
                                <label class="form-label">Description</label>
                                <textarea class="form-control" rows="2" value="@entry.Description"
                                          @onchange="e => UpdateWork(idx, entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
                            </div>
                        </div>
                    </div>
                </div>
            }

            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>

            <div class="step-buttons">
                <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                <button class="btn btn-primary" @onclick="NextFromWork">Next &raquo;</button>
            </div>
        </section>
    }

    @* ───── Step 3: References ───── *@
    @if (_currentStep == 2)
    {
        <section class="step-content">
            <h2>References</h2>

            @for (int i = 0; i < _references.Count; i++)
            {
                var idx = i;
                var r = _references[idx];

                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Reference @(idx + 1)</h5>
                            @if (_references.Count > 2)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(idx)">Remove</button>
                            }
                        </div>

                        <div class="row g-3">
                            <div class="col-md-6">
                                <label class="form-label">Name <span class="text-danger">*</span></label>
                                <input class="form-control" value="@r.Name"
                                       @onchange="e => UpdateRef(idx, r with { Name = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                <input class="form-control" value="@r.Relationship"
                                       @onchange="e => UpdateRef(idx, r with { Relationship = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Email <span class="text-danger">*</span></label>
                                <input class="form-control" type="email" value="@r.Email"
                                       @onchange="e => UpdateRef(idx, r with { Email = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Phone <span class="text-danger">*</span></label>
                                <input class="form-control" type="tel" value="@r.Phone"
                                       @onchange="e => UpdateRef(idx, r with { Phone = (string?)e.Value ?? string.Empty })" />
                            </div>
                        </div>
                    </div>
                </div>
            }

            @if (_references.Count < 3)
            {
                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
            }

            <div class="step-buttons">
                <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                <button class="btn btn-primary" @onclick="NextFromReferences">Next &raquo;</button>
            </div>
        </section>
    }

    @* ───── Step 4: Cover Letter ───── *@
    @if (_currentStep == 3)
    {
        <section class="step-content">
            <h2>Cover Letter</h2>

            <div class="mb-2">
                <textarea class="form-control" rows="12" maxlength="2000"
                          @bind="_coverLetter" @bind:event="oninput"
                          placeholder="Tell us why you're a great fit for this role…"></textarea>
            </div>
            <div class="text-end text-muted mb-3">
                @(_coverLetter?.Length ?? 0) / 2000 characters
            </div>

            <div class="step-buttons">
                <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next &raquo;</button>
            </div>
        </section>
    }

    @* ───── Step 5: Review & Submit ───── *@
    @if (_currentStep == 4)
    {
        <section class="step-content">
            <h2>Review &amp; Submit</h2>

            @if (_submitted)
            {
                <div class="alert alert-success text-center py-4">
                    <h3>&#10003; Application Submitted!</h3>
                    <p class="mb-0">Your application ID is <strong>#@_applicationId</strong>. We'll be in touch!</p>
                </div>
            }
            else
            {
                @* Personal Info *@
                <div class="review-section">
                    <div class="review-header">
                        <h5>Personal Information</h5>
                        <button class="btn btn-link btn-sm" @onclick='() => GoToStep(0)'>Edit</button>
                    </div>
                    <dl class="row mb-0">
                        <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@_fullName</dd>
                        <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                        <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                        <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                    </dl>
                </div>

                @* Work History *@
                <div class="review-section">
                    <div class="review-header">
                        <h5>Work History</h5>
                        <button class="btn btn-link btn-sm" @onclick='() => GoToStep(1)'>Edit</button>
                    </div>
                    @foreach (var w in _workEntries)
                    {
                        <div class="mb-2">
                            <strong>@w.Title</strong> at @w.Company<br />
                            <small class="text-muted">
                                @w.StartDate.ToString("MMM yyyy") &ndash;
                                @(w.IsCurrent ? "Present" : w.EndDate?.ToString("MMM yyyy"))
                            </small>
                            @if (!string.IsNullOrWhiteSpace(w.Description))
                            {
                                <p class="mb-0 mt-1">@w.Description</p>
                            }
                        </div>
                    }
                </div>

                @* References *@
                <div class="review-section">
                    <div class="review-header">
                        <h5>References</h5>
                        <button class="btn btn-link btn-sm" @onclick='() => GoToStep(2)'>Edit</button>
                    </div>
                    @foreach (var r in _references)
                    {
                        <div class="mb-2">
                            <strong>@r.Name</strong> (@r.Relationship)<br />
                            <small>@r.Email &middot; @r.Phone</small>
                        </div>
                    }
                </div>

                @* Cover Letter *@
                <div class="review-section">
                    <div class="review-header">
                        <h5>Cover Letter</h5>
                        <button class="btn btn-link btn-sm" @onclick='() => GoToStep(3)'>Edit</button>
                    </div>
                    <p style="white-space: pre-wrap;">@_coverLetter</p>
                </div>

                <div class="step-buttons">
                    <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_submitting">
                        @if (_submitting)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span> @:Submitting…
                        }
                        else
                        {
                            @:Submit Application
                        }
                    </button>
                </div>
            }
        </section>
    }
</div>

