{"file_text": ".apply-container {
    max-width: 820px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* ── Step indicator bar ── */

.step-bar {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
    margin-bottom: 2rem;
    flex-wrap: wrap;
}

.step-bar .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    padding: 0.5rem 0.75rem;
    cursor: default;
    min-width: 90px;
}

.step-bar .step.completed {
    cursor: pointer;
}

.step-number {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.95rem;
    margin-bottom: 0.35rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #adb5bd;
    transition: all 0.2s;
}

.step.active .step-number {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

.step.completed .step-number {
    background: #198754;
    color: #fff;
    border-color: #198754;
}

.step-label {
    font-size: 0.78rem;
    color: #adb5bd;
    text-align: center;
    white-space: nowrap;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step-connector {
    width: 32px;
    height: 2px;
    background: #dee2e6;
    align-self: center;
    margin-bottom: 1.2rem;
}

.step-connector.done {
    background: #198754;
}

/* ── Step content ── */

.step-content {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.75rem;
}

.step-content h2 {
    margin-bottom: 1.25rem;
    font-size: 1.35rem;
}

/* ── Step navigation buttons ── */

.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

/* ── Review section ── */

.review-section {
    border: 1px solid #e9ecef;
    border-radius: 0.375rem;
    padding: 1rem 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.review-header h5 {
    margin-bottom: 0;
}
